facts={'schema':'DEE.PI09.final_document_facts.R02','internal_edition':'1.38','closed_for_authoring':False,'selected_life':copy.deepcopy(base['selected_life']),'selected_life_is_provisional_for_final_editorial_cut':True,'cut_utc':datetime.now(timezone.utc).isoformat(),'description':'Borrador editorial PI09. C1 incorporado y repetición familiar real. D: contraste cerrado5/6,3/6,1/6 y revisión de cadena compartida. Sin presuponer adopción D ni resultados finales pendientes.','evidence':[ref(n)for n in names],'front':{'edition_summary':'Edición1.38 preparada. Primer hito Native12/12 incorporado. D experimental5/6 frente a3/6 y1/6, con límites de crédito compartido. Root debe cerrar incorporación y conservación finales.','principal_summary':'Principal confirmado al borrador: ECI02_PI03_REPRO_PI04_PI05_PI07_PI09_NATIVE_01, fisica_directa, N67/T903603. Misma vida completa, padre C884835 y ascendencia B/A. D todavía no sustituye al principal.','functional_summary':'Dos selecciones Native dentro de una secuencia preparada: acceso material a información registrada y actuación útil. El contenido contribuye causalmente. D revisa la cadena compartida tras un fallo propio. No se demuestra crédito individual de preguntar ni agencia general.','conservation_summary':'Hito1: dos clones12/12 más5/5. Ayuda temporal P0 sin ganancia adicional. Estado del principal comprobado por reapertura pública0 e igualdad Native, sin nueva oportunidad material. Conservación final D pendiente.','resume_summary':'Reabrir la vida existente mediante acceso principal o gestor pausado, sin --nueva. Al borrador: consulta12/18, C2C31/32 y FI4/8. Los contadores finales y el permiso operativo deben actualizarse desde el comprobante real si Root adopta D.','coverage_summary':'Lectura dirigida de contratos, código y primarios decisivos. Reutilización explícita de PI01–PI08. Native real, recálculo documental, pruebas puras y preparación se distinguen. No se declara nueva lectura integral del corpus.','control_table':{'Documento':'DCS11-MM-001 / Edición documental1.38 / PI09 / BORRADOR NO AUTORIZADO PARA AUTORÍA','Corte de liberación registrado':'Pendiente de cierre Root. Principal confirmado Native903603. D experimental917679, ordinal6, sin adopción atribuida.','Base principal':'Manual completo1.37 y Compendio completos preservados. Añadir capítulo54 y mantener capítulos1–53 y apéndices literales.','Estado de esta edición':'closed_for_authoring:false. Faltan conservación y función final D, cierre RP_DRf6 y decisión efectiva. No ejecutar autoría/publicación desde este borrador.'}},'manual_sections':manual,'compendium_sections':compendium,'pending_finalization':{'D_adoption':'Root debe decidir mediante gates reales, no por este borrador','D_conservation':'PENDIENTE_COMPROBANTE_CERRADO','D_last_use_after_reopen':'PENDIENTE_COMPROBANTE_CERRADO','D_source_reopening0':'control/REAPERTURA_SOURCE_D_PI09_R01.json todavía no se cita como evidencia','D_material_replay':'EN_CURSO_AL_BORRADOR; no se lee el mundo vivo','final_ledger_and_world_count':'No se adivinan; Root añadirá ledger cerrado','final_selected_identity_tick_snapshot_and_stock':'Reemplazar exclusivamente con pruebas actuales después de la decisión','publication_1_38':'NO_EJECUTADA','visual_QA_1_38':'NO_REALIZADA'},'Native_executed_by_preparation':False,'DOCX_authored_or_modified':False,'product_written':False}
